// Validate payload and route determination
const body = $input.first().json.body || $input.first().json;

const appId = body.applicationId || 'AICTE-' + new Date().getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000);
const institutionName = body.application?.institutionName || body.institutionName || 'Unknown Institution';
const route = body.application?.processingRoute || body.processingRoute || 'Scrutiny followed by EVC';
const region = body.application?.region || body.region || 'Western';

// Calculate default stage deadline (15 days for scrutiny)
const now = new Date();
const scrutinyDeadline = new Date(now.getTime() + 15 * 24 * 60 * 60 * 1000);

// Determine initial stage and next scrutiny queue
let initialStage = 'Automated Pre-Screening';
let assignedQueue = 'Scrutiny Committee (' + region + ' Region)';

return [{
  json: {
    applicationId: appId,
    institutionName: institutionName,
    processingRoute: route,
    region: region,
    currentStage: initialStage,
    currentStatus: 'Application Registered - In Automated Pre-Screening Queue',
    stageDeadline: scrutinyDeadline.toISOString(),
    assignedQueue: assignedQueue,
    submittedAt: now.toISOString(),
    submittedBy: body.submittedBy || 'college.admin@aicte.edu.in',
    auditAction: 'SUBMIT_APPLICATION',
    notificationSubject: 'AICTE Application Registered: ' + appId,
    notificationMessage: `Dear Institution, your application ${appId} for ${route} has been accepted and assigned to ${assignedQueue}. Scrutiny deadline is ${scrutinyDeadline.toISOString().split('T')[0]}.`
  }
}];
